package com.dy.artisan3d.data.remote.pagingimport androidx.paging.PagingSourceimport androidx.paging.PagingStateimport com.dy.artisan3d.data.model.ProductListResponseimport com.dy.artisan3d.domain.model.NetworkErrorimport com.dy.artisan3d.domain.model.Productimport com.dy.artisan3d.util.Constants.BASE_URLimport com.dy.artisan3d.util.Constants.FILE_URLimport com.dy.artisan3d.util.toNetworkErrorimport io.github.aakira.napier.Napierimport io.ktor.client.HttpClientimport io.ktor.client.call.bodyimport io.ktor.client.request.getimport io.ktor.client.request.parameterimport kotlinx.io.IOExceptionimport kotlinx.serialization.SerializationExceptionclass ProductPagingSource(    private val httpClient: HttpClient,    private val lang: String,    private val categoryId: Int? = null, // null bo'lsa barchasi olinadi    private val brandId: Int? = null,) : PagingSource<Int, Product>() {    override suspend fun load(params: LoadParams<Int>): LoadResult<Int, Product> {        val page = params.key ?: 1        return try {            val response: ProductListResponse = httpClient.get(BASE_URL + "products") {                parameter("page", page)                if (categoryId != null && categoryId > 0) {                    parameter("category_id", categoryId)                }                if (brandId != null && brandId > 0) {                    parameter("brand_id", brandId)                }            }.body()            val products = response.data.map { dto ->                val translation = dto.translations[lang]                    ?: dto.translations["uz"]                    ?: dto.translations.values.firstOrNull()                Product(                    id = dto.id,                    name = translation?.name ?: "Nomsiz",                    description = translation?.description ?: "",                    imageUrl = FILE_URL + dto.images.main,                    glbUrl = dto.images.glb?.let { FILE_URL + it },                    badge = dto.details.firstOrNull()?.materials?.firstOrNull()?.translations?.get(lang)?.name ?: ""                )            }            val meta = response.meta            LoadResult.Page(                data = products,                prevKey = if (page <= 1) null else page - 1,                nextKey = if (page >= meta.last_page) null else page + 1            )        } catch (e: Exception) {            Napier.e(tag = "ARTISAN_DEBUG", throwable = e) { "Paging Error" }            LoadResult.Error(e.toNetworkError())        }    }    override fun getRefreshKey(state: PagingState<Int, Product>): Int? {        // Bu yerda null qaytarish - refresh bo'lganda har doim        // initialKey (ya'ni 1-sahifa)dan boshlashni anglatadi.        return null    }}